from typing import List, Tuple


def max_alkane_vertices(n: int, edges: List[Tuple[int, int]]) -> int:
    """Return the largest subtree whose degrees are 1 or 4, with a degree-4 vertex.

    Return -1 when no such subtree exists. Vertices are numbered 1 through n.
    Runs in O(n) time and space, without recursion.
    """
    adjacency = [[] for _ in range(n + 1)]
    for a, b in edges:
        adjacency[a].append(b)
        adjacency[b].append(a)

    parent = [0] * (n + 1)
    order = [1]
    for vertex in order:
        for neighbor in adjacency[vertex]:
            if neighbor != parent[vertex]:
                parent[neighbor] = vertex
                order.append(neighbor)

    # branch[v] includes v and assumes its edge to its parent is selected.
    # Thus v is either a leaf, or uses exactly three child branches.
    branch = [1] * (n + 1)
    answer = -1
    for vertex in reversed(order):
        largest = []
        for child in adjacency[vertex]:
            if parent[child] == vertex:
                largest.append(branch[child])
                largest.sort(reverse=True)
                if len(largest) > 4:
                    largest.pop()

        if len(largest) >= 3:
            branch[vertex] = 1 + sum(largest[:3])
            if parent[vertex]:
                # The parent may be the topmost leaf of the chosen subtree.
                answer = max(answer, branch[vertex] + 1)
        if len(largest) == 4:
            # Here vertex is the topmost vertex and has four children.
            answer = max(answer, 1 + sum(largest))
    return answer

def count_good_string_replacements(n: int, k: int, s: str) -> int:
    """Count replacements having at least k deletable contiguous substrings.

    Pairs of equal letters and triples ABC may be deleted. A substring is
    deletable exactly when the three letter counts have the same parity.
    Return the number of replacements modulo 998244353 (n <= 50).
    """
    mod = 998244353
    if k == 0:
        return pow(3, s.count('?'), mod)
    # Consecutive prefix XOR values differ, so each value occurs at most
    # ceil((n + 1) / 2) times. Concentrating visits on two values maximizes
    # the number of equal-prefix pairs.
    if k > n * n // 4:
        return 0

    # Counts are indexed relative to the current prefix XOR. This removes
    # the need to store the endpoint separately. Initially only the empty
    # prefix has been visited.
    dp = {(1, 0, 0, 0): 1}
    codes = {'A': 1, 'B': 2, 'C': 3}
    for ch in s:
        choices = (1, 2, 3) if ch == '?' else (codes[ch],)
        following = {}
        for counts, ways in dp.items():
            for step in choices:
                state = (counts[step] + 1, counts[1 ^ step],
                         counts[2 ^ step], counts[3 ^ step])
                total = following.get(state, 0) + ways
                if total >= mod:
                    total -= mod
                following[state] = total
        dp = following

    # Every pair of equal prefix XORs identifies one nonempty good substring.
    return sum(ways for counts, ways in dp.items()
               if sum(c * (c - 1) // 2 for c in counts) >= k) % mod

