def count_valid_grids(H: int, W: int, grid: list[str]) -> int:
    """Count proper three-colour completions, modulo 998244353.

    Every edge-sharing pair must have different digits. The frontier stores
    the most recently visited cell in each column; transposition keeps its
    width at most sqrt(H * W).
    """
    mod = 998244353
    if W > H:
        grid = ["".join(grid[r][c] for r in range(H)) for c in range(W)]
        H, W = W, H

    # Reject incompatible fixed cells before building the frontier.
    for r in range(H):
        for c in range(W):
            digit = grid[r][c]
            if digit == "?":
                continue
            if r and grid[r - 1][c] == digit:
                return 0
            if c and grid[r][c - 1] == digit:
                return 0

    # Two bits per cell, with zero reserved for unvisited cells.
    shift = 2 * (W - 1)
    mask = (1 << (2 * W)) - 1
    choices = {
        (above, left): tuple(
            digit for digit in (1, 2, 3)
            if digit != above and digit != left
        )
        for above in range(4)
        for left in range(4)
    }
    dp = {0: 1}
    for r in range(H):
        for c in range(W):
            fixed = grid[r][c]
            next_dp = {}
            if fixed == "?":
                for state, count in dp.items():
                    above = state >> shift
                    left = (state & 3) if c else 0
                    base = (state << 2) & mask
                    for digit in choices[above, left]:
                        target = base | digit
                        next_dp[target] = (next_dp.get(target, 0) + count) % mod
            else:
                digit = int(fixed)
                for state, count in dp.items():
                    if state >> shift == digit:
                        continue
                    if c and state & 3 == digit:
                        continue
                    target = ((state << 2) & mask) | digit
                    next_dp[target] = (next_dp.get(target, 0) + count) % mod
            dp = next_dp
            if not dp:
                return 0
    return sum(dp.values()) % mod

from typing import List
from math import gcd


def kth_smallest_amount(coins: List[int], k: int) -> int:
    """Return the kth distinct positive multiple of any supplied denomination.

    Coins of different denominations cannot be combined. Denominations are
    positive integers and k is one-based.
    """
    denominations = []
    for coin in sorted(set(coins)):
        if not any(coin % smaller == 0 for smaller in denominations):
            denominations.append(coin)

    # Aggregate inclusion-exclusion terms that share an LCM.
    coefficients = {}
    for coin in denominations:
        changes = {coin: 1}
        for multiple, coefficient in coefficients.items():
            common = multiple // gcd(multiple, coin) * coin
            changes[common] = changes.get(common, 0) - coefficient
        for multiple, change in changes.items():
            coefficient = coefficients.get(multiple, 0) + change
            if coefficient:
                coefficients[multiple] = coefficient
            else:
                coefficients.pop(multiple, None)

    terms = tuple(coefficients.items())
    low, high = 1, denominations[0] * k
    while low < high:
        middle = (low + high) // 2
        count = sum((middle // multiple) * coefficient
                    for multiple, coefficient in terms)
        if count >= k:
            high = middle
        else:
            low = middle + 1
    return low

