def _suffix_count(length: int, digit_sum: int, needed: int) -> int:
    """Count nonzero-digit suffixes with this sum and product requirement."""
    if digit_sum < length or digit_sum > 9 * length:
        return 0
    if length == 0:
        return int(digit_sum == 0 and needed == 1)
    return sum(
        _suffix_count(length - 1, digit_sum - digit, needed // gcd(needed, digit))
        for digit in range(1, 10)
    )


def _count_up_to(bound: int) -> int:
    if bound <= 0:
        return 0
    digits = [int(c) for c in str(bound)]
    length = len(digits)

    # Every positive number containing a zero has digit product zero.
    nonzero_count = sum(9 ** size for size in range(1, length))
    for index, digit in enumerate(digits):
        if digit == 0:
            break
        nonzero_count += (digit - 1) * 9 ** (length - index - 1)
    else:
        nonzero_count += 1
    answer = bound - nonzero_count

    # A product of nonzero decimal digits has no prime factors above seven.
    for target_sum in range(1, 9 * length + 1):
        rest = target_sum
        for prime in (2, 3, 5, 7):
            while rest % prime == 0:
                rest //= prime
        if rest != 1:
            continue

        for size in range(1, length):
            answer += _suffix_count(size, target_sum, target_sum)

        remaining_sum = target_sum
        needed = target_sum
        for index, digit in enumerate(digits):
            for smaller in range(1, digit):
                answer += _suffix_count(
                    length - index - 1,
                    remaining_sum - smaller,
                    needed // gcd(needed, smaller),
                )
            if digit == 0:
                break
            remaining_sum -= digit
            needed //= gcd(needed, digit)
        else:
            answer += int(remaining_sum == 0 and needed == 1)
    return answer


def count_beautiful_numbers(l: int, r: int) -> int:
    """ Count the number of beautiful numbers in the range [l, r] inclusive.

    A positive integer is called beautiful if the product of its digits is divisible by the sum of its digits.

    Args:
        l: The lower bound of the range (inclusive)
        r: The upper bound of the range (inclusive)

    Returns:
        The count of beautiful numbers in the range [l, r]

    Constraints:
        1 <= l <= r < 10^9

    >>> count_beautiful_numbers(10, 20)
    2
    >>> count_beautiful_numbers(1, 15)
    10
    >>> count_beautiful_numbers(4, 4)
    1
    """
    return _count_up_to(r) - _count_up_to(l - 1)

def max_partitions_with_one_change(s: str, k: int) -> int:
    """Return the maximum greedy partition count after at most one replacement.

    Each partition is the longest remaining prefix with at most k distinct
    lowercase letters. The input has length 1..10000 and 1 <= k <= 26.
    """
    if not s:
        return 0
    if k == 26 or len(set(s)) < k:
        return 1

    # An unchanged prefix has one greedy state. For prefixes whose change
    # has been spent, keep the best count for each current-partition mask.
    # Equal masks have identical future behavior, so smaller counts can go.
    unchanged_mask = 0
    unchanged_count = 1
    changed = {}
    letters = [1 << i for i in range(26)]
    for char in s:
        bit = 1 << (ord(char) - ord('a'))
        next_changed = {}
        for mask, count in changed.items():
            merged = mask | bit
            if merged.bit_count() > k:
                merged = bit
                count += 1
            if count > next_changed.get(merged, 0):
                next_changed[merged] = count

        # Spend the one allowed change at this position. Including the
        # original letter also represents choosing not to make a change.
        for replacement in letters:
            merged = unchanged_mask | replacement
            count = unchanged_count
            if merged.bit_count() > k:
                merged = replacement
                count += 1
            if count > next_changed.get(merged, 0):
                next_changed[merged] = count

        merged = unchanged_mask | bit
        if merged.bit_count() > k:
            unchanged_mask = bit
            unchanged_count += 1
        else:
            unchanged_mask = merged
        changed = next_changed

    return max(unchanged_count, max(changed.values(), default=0))

