def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """Determine whether some of the rotatable tiles exactly cover an h by w grid.

    Tiles align with grid cells, may not overlap or extend outside the grid,
    and each available tile may be used at most once.
    """
    shapes = [tuple(sorted(tile)) for tile in tiles[:n]
              if (tile[0] <= h and tile[1] <= w)
              or (tile[1] <= h and tile[0] <= w)]
    count = len(shapes)
    full = (1 << (h * w)) - 1
    areas = [a * b for a, b in shapes]

    # Bit k of possible[mask] says that a subset of mask has total area k.
    possible = [1] * (1 << count)
    for mask in range(1, 1 << count):
        bit = mask & -mask
        i = bit.bit_length() - 1
        rest = possible[mask ^ bit]
        possible[mask] = rest | (rest << areas[i])

    placements = []
    for a, b in shapes:
        by_cell = []
        for cell in range(h * w):
            row, col = divmod(cell, w)
            options = []
            for height, width in {(a, b), (b, a)}:
                if row + height <= h and col + width <= w:
                    rectangle = 0
                    strip = (1 << width) - 1
                    for offset in range(height):
                        rectangle |= strip << (cell + offset * w)
                    options.append(rectangle)
            by_cell.append(options)
        placements.append(by_cell)

    @lru_cache(None)
    def search(occupied: int, remaining: int) -> bool:
        if occupied == full:
            return True
        needed = h * w - occupied.bit_count()
        if not (possible[remaining] >> needed) & 1:
            return False
        empty = full ^ occupied
        cell = (empty & -empty).bit_length() - 1
        seen = set()
        for i, shape in enumerate(shapes):
            bit = 1 << i
            if not remaining & bit or shape in seen:
                continue
            seen.add(shape)
            # The first uncovered cell must be the top-left cell of its tile:
            # every cell earlier in row order is already occupied.
            for rectangle in placements[i][cell]:
                if not rectangle & occupied:
                    if search(occupied | rectangle, remaining ^ bit):
                        return True
        return False

    return search(0, (1 << count) - 1)

def count_valid_grids(H: int, W: int, grid: list[str]) -> int:
    """ Given a grid with H rows and W columns consisting of '1', '2', '3', and '?',
    count how many ways we can replace each '?' with '1', '2', or '3' such that
    any two adjacent (edge-sharing) cells contain different digits.

    Return the count modulo 998244353.

    Args:
        H: Number of rows (1 <= H, H * W <= 200)
        W: Number of columns (1 <= W, H * W <= 200)
        grid: List of strings representing the grid, where grid[i] is the i-th row

    Returns:
        The number of valid grid configurations modulo 998244353

    >>> count_valid_grids(2, 2, ['1?', '??'])
    6
    >>> count_valid_grids(2, 3, ['123', '3?1'])
    0
    >>> count_valid_grids(1, 1, ['?'])
    3
    """
    mod = 998244353
    if W > H:
        grid = ["".join(grid[r][c] for r in range(H)) for c in range(W)]
        H, W = W, H

    # Reject incompatible fixed cells before building the frontier.
    for r in range(H):
        for c in range(W):
            digit = grid[r][c]
            if digit == "?":
                continue
            if r and grid[r - 1][c] == digit:
                return 0
            if c and grid[r][c - 1] == digit:
                return 0

    # Two bits per cell, with zero reserved for unvisited cells.
    shift = 2 * (W - 1)
    mask = (1 << (2 * W)) - 1
    choices = {
        (above, left): tuple(
            digit for digit in (1, 2, 3)
            if digit != above and digit != left
        )
        for above in range(4)
        for left in range(4)
    }
    dp = {0: 1}
    for r in range(H):
        for c in range(W):
            fixed = grid[r][c]
            next_dp = {}
            if fixed == "?":
                for state, count in dp.items():
                    above = state >> shift
                    left = (state & 3) if c else 0
                    base = (state << 2) & mask
                    for digit in choices[above, left]:
                        target = base | digit
                        next_dp[target] = (next_dp.get(target, 0) + count) % mod
            else:
                digit = int(fixed)
                for state, count in dp.items():
                    if state >> shift == digit:
                        continue
                    if c and state & 3 == digit:
                        continue
                    target = ((state << 2) & mask) | digit
                    next_dp[target] = (next_dp.get(target, 0) + count) % mod
            dp = next_dp
            if not dp:
                return 0
    return sum(dp.values()) % mod

def can_transform(k: int, s: str, t: str) -> bool:
    """Return whether insertions, deletions and replacements can turn s into t
    using at most k operations.

    Tracks the furthest reachable source position on each diagonal after each
    edit count, extending every state through a maximal run of equal characters.
    Time is O((len(s) + len(t)) * k + k**2); auxiliary space is O(k).
    """
    n, m = len(s), len(t)
    if abs(n - m) > k:
        return False
    if k >= max(n, m):
        return True

    i = 0
    while i < n and i < m and s[i] == t[i]:
        i += 1
    if i == n and i == m:
        return True
    # A diagonal d represents source_index - target_index.
    previous = {0: i}
    for edits in range(1, k + 1):
        current = {}
        for d in range(max(-edits, -m), min(edits, n) + 1):
            best = -1
            # Replace the next character.
            x = previous.get(d, -1)
            if x >= 0 and x < n and x - d < m:
                best = x + 1
            # Delete a source character, moving to diagonal d.
            x = previous.get(d - 1, -1)
            if x >= 0 and x < n:
                best = max(best, x + 1)
            # Insert a target character, moving to diagonal d.
            x = previous.get(d + 1, -1)
            if x >= 0 and x - (d + 1) < m:
                best = max(best, x)
            if best < 0:
                continue
            j = best - d
            while best < n and j < m and s[best] == t[j]:
                best += 1
                j += 1
            if best == n and j == m:
                return True
            current[d] = best
        previous = current
    return False

